                idx = int(idx_str)
                if idx < 1:
                    has_malformed = True
                    break
            except ValueError:
                has_malformed = True
                break
            if not re.match(r'^n\d+$', node):
                has_malformed = True
                break
            parsed_raw.append((term, idx, node, op, data))
        else:
            has_malformed = True
            break

    # Group by index and filter exact duplicates within each index
    entries_by_index = {}  # index -> list of (term, node, op, data) in file order
    for entry in parsed_raw:
        term, idx, node, op, data = entry
        if idx not in entries_by_index:
            entries_by_index[idx] = []
        is_dup = False
        for existing in entries_by_index[idx]:
            ex_term, ex_node, ex_op, ex_data = existing
            if term == ex_term and node == ex_node and op == ex_op and data == ex_data:
                is_dup = True
                break
        if not is_dup:
            entries_by_index[idx].append((term, node, op, data))  # store without index

    violations = []  # list of "BAD <index> <reason>" strings
    index_has_violation = set()  # indices that have any BAD violation

    # Global tracking for Rule 3 using parsed_raw in file order
    node_votes = {}  # term -> set of nodes that have voted
    first_leader_index = {}  # term -> index of first LEADER

    # Process parsed_raw in file order for Rule 3 AND check for BAD_OPERATION
    for term, idx, node, op, data in parsed_raw:
        if op == 'VOTE':
            if term not in node_votes:
                node_votes[term] = set()
            if node in node_votes[term]:
                violations.append(f"BAD {idx} BAD_DUPLICATE_VOTE")
                index_has_violation.add(idx)
            node_votes[term].add(node)
        elif op == 'COMMIT':
            # COMMIT is a valid op but only checked against APPEND later
            pass  # Will be checked in Rule 4 logic
        elif op == 'LEADER':
            if term not in first_leader_index:
                first_leader_index[term] = idx
            else:
                violations.append(f"BAD {idx} BAD_LEADER_ORDER")
                index_has_violation.add(idx)
        elif op == 'APPEND':
            # Should not happen here since APPEND requires 5 fields
            pass
        else:
            # Unknown operation type -> BAD_OPERATION
            violations.append(f"BAD {idx} BAD_OPERATION")
            index_has_violation.add(idx)

    # Now process each index for local rules (1, 4, 5)
    all_indices = set(entries_by_index.keys())
    for idx in all_indices:
        entries = entries_by_index[idx]

        # Rule 1: Term monotonicity
        prev_term = None
        term_regression = False
        for term, node, op, data in entries:
            if prev_term is not None and term < prev_term:
                term_regression = True
            prev_term = term
        if term_regression:
            violations.append(f"BAD {idx} BAD_TERM_REGRESSION")
            index_has_violation.add(idx)

        # Rule 5: conflicts and determine winning term - only consider APPENDs
        appends = [(t, n, o, d) for t, n, o, d in entries if o == 'APPEND']
        conflict = False
        if appends:
            term_to_data = {}
            for t, n, o, d in appends:
                if t not in term_to_data:
                    term_to_data[t] = set()
                term_to_data[t].add(d)
            for t, data_set in term_to_data.items():
                if len(data_set) > 1:
                    conflict = True
                    break
        if conflict:
            violations.append(f"BAD {idx} BAD_CONFLICT")
            index_has_violation.add(idx)

        # Determine winning term from APPENDs
        if appends:
            max_term = max(a[0] for a in appends)
            winning_term = max_term
        else:
            winning_term = None

        # Rule 4: Commit semantics - check APPENDs and COMMITs
        has_appends = len(appends) > 0
        commit_entries = [(t, n, o, d) for t, n, o, d in entries if o == 'COMMIT']
        has_commits = len(commit_entries) > 0

        if has_appends and not has_commits:
            # Has APPENDs but no COMMIT - potential repair
            pass
        elif has_commits:
            seen_append_before = False
            commit_order_bad = False
            commit_term_mismatch = False
            for t, n, o, d in entries:
                if o == 'APPEND':
                    seen_append_before = True
                if o == 'COMMIT':
                    if not seen_append_before:
                        commit_order_bad = True
                    if t != winning_term:
                        commit_term_mismatch = True
            if commit_order_bad or commit_term_mismatch:
                violations.append(f"BAD {idx} BAD_COMMIT_ORDER")
                index_has_violation.add(idx)

    # Rule 2: Log matching property - run after all other rules
    index_commit_terms = {}
    for idx in entries_by_index:
        entries = entries_by_index[idx]
        commit_terms = []
        for t, n, o, d in entries:
            if o == 'COMMIT':
                commit_terms.append(t)
        index_commit_terms[idx] = commit_terms

    all_index_nums = sorted(entries_by_index.keys())
    for i_idx in all_index_nums:
        if i_idx in index_commit_terms:
            for T in index_commit_terms[i_idx]:
                next_idx = i_idx + 1
                if next_idx in entries_by_index:
                    entries_next = entries_by_index[next_idx]
                    has_violation = False
                    for term, node, op, data in entries_next:
                        if term < T:
                            has_violation = True
                            break
                    if has_violation:
                        violations.append(f"BAD {next_idx} BAD_LOG_MATCH")
                        index_has_violation.add(next_idx)

    # Now determine repairs: only for indices with APPENDs but no commits AND no violations at all AND no malformed line
    repairs = []
    if not has_malformed:
        for idx in entries_by_index:
            entries = entries_by_index[idx]
            appends = [(t, n, o, d) for t, n, o, d in entries if o == 'APPEND']
            has_appends = len(appends) > 0
            has_commits = any(o == 'COMMIT' for t, n, o, d in entries)

            if has_appends and not has_commits and idx not in index_has_violation:
                if appends:
                    max_term = max(a[0] for a in appends)
                    repairs.append(f"INS {max_term} {idx} COMMIT")

    # Sort violations by index
    bad_lines_sorted = []
    for v in violations:
        match = re.match(r'BAD (\d+) (.+)', v)
        if match:
            idx = int(match.group(1))
            full_line = v
            bad_lines_sorted.append((idx, full_line))
    bad_lines_sorted.sort(key=lambda x: x[0])

    # Sort repairs by (index, term)
    repairs_sorted = []
    for r in repairs:
        parts = r.split()
        term = int(parts[1])
        idx = int(parts[2])
        repairs_sorted.append((idx, term, r))
    repairs_sorted.sort(key=lambda x: (x[0], x[1]))

    output = []
    for _, line in bad_lines_sorted:
        output.append(line)
    for _, _, line in repairs_sorted:
        output.append(line)

    if not output:
        return "OK"
    return "\n".join(output)
EOF"}
